// ===================== shared art (from self-vs-agent) =====================
const bagL=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-62 -40 Q-62 -118 0 -118 Q62 -118 62 -40" fill="none" stroke="#5a2e14" stroke-width="16" stroke-linecap="round"/><rect x="-115" y="-50" width="230" height="165" rx="28" fill="#a0522d"/><path d="M-115 -12 H115 V26 Q0 62 -115 26Z" fill="#7c3f1c"/><rect x="-20" y="16" width="40" height="32" rx="7" fill="#f2b705"/><path d="M-98 -34 H98 M-98 98 H98" stroke="#d08a58" stroke-width="4" stroke-dasharray="10 8"/></g>`;
function ttl(P,n,txt,col,y=410){return `<g data-k="${P}tt">${card(70,y,940,150,'#fff',40)}<circle cx="165" cy="${y+75}" r="54" fill="${col}"/>${tx(165,y+98,n,62,'#fff',800)}${tx(245,y+96,txt,48,C.ink,800,'start')}</g>`}
function subH(P,k,txt,col,ic,y=410){return `<g data-k="${P}tt">${card(70,y,940,150,'#fff',40)}<circle cx="165" cy="${y+75}" r="54" fill="${col}"/>${ic(165,y+75)}${tx(245,y+60,k,30,C.mute,700,'start')}${tx(245,y+118,txt,50,C.ink,800,'start')}</g>`}
function browser(x,y,w,h,url,col=C.g){return `${card(x,y,w,h,'#fff',28)}<rect x="${x}" y="${y}" width="${w}" height="72" rx="28" fill="${col}"/><rect x="${x}" y="${y+40}" width="${w}" height="32" fill="${col}"/>${[0,1,2].map(i=>`<circle cx="${x+38+i*28}" cy="${y+36}" r="9" fill="#fff" opacity=".75"/>`).join('')}<rect x="${x+130}" y="${y+16}" width="${w-160}" height="40" rx="20" fill="#fff"/>${lat(x+152,y+44,url,23,C.mute,600,'start')}`}
function bub(x,y,w,txt,col='#fff',fg=C.ink,size=34,tail=-1){return `<g filter="url(#sh2)"><rect x="${x-w/2}" y="${y-48}" width="${w}" height="96" rx="30" fill="${col}"/><path d="M${x+tail*40} ${y+44} l${tail*10} 34 l${-tail*40} -34Z" fill="${col}"/></g>${tx(x,y+12,txt,size,fg,800)}`}
function field(x,y,w,label,col,id){return `${tx(x,y,label,26,C.mute,700,'start')}<rect x="${x}" y="${y+14}" width="${w}" height="34" rx="10" fill="#eef2f6"/><rect data-k="${id}" x="${x}" y="${y+14}" width="0" height="34" rx="10" fill="${col}" opacity=".55"/>`}
const ic=(n,col='#fff',sz=64,w=8)=>(x,y)=>icon(n,x,y,sz,col,w);
const folder=(x,y,col)=>`<g><path d="M${x} ${y} h60 l14 16 h86 v96 h-160Z" fill="${col}"/><rect x="${x}" y="${y+24}" width="160" height="88" rx="8" fill="${col}" opacity=".85"/></g>`;
const fillTo=(el,lt,b,w,d=.9)=>setW(el,w*eio(cl((lt-b)/d)));

const shipA=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-170 0 H170 L130 70 H-140Z" fill="${C.bd}"/><rect x="-170" y="-8" width="340" height="14" fill="${C.r}"/>${[0,1,2,3,4,5].map(i=>`<rect x="${-150+i*48}" y="-58" width="44" height="48" fill="${[C.o,C.g,C.b,C.y,C.t,C.r][i]}"/>`).join('')}${[0,1,2,3].map(i=>`<rect x="${-126+i*48}" y="-104" width="44" height="44" fill="${[C.t,C.y,C.g,C.o][i]}"/>`).join('')}<rect x="110" y="-120" width="44" height="110" fill="#fff" stroke="${C.bd}" stroke-width="4"/></g>`;
